// nisargadatta_te.dart
// Nisargadatta maharaj quotes and articles (Malyalam)

import '../articlesquotes.dart';

final nisargadattaSaint = Saint(
  'nisargadatta',
  'നിസർഗദത്ത മഹാരാജ്',
  'assets/images/nisargadatta.jpg',
  [
    'നീ സ്വയം കരുതുന്നതല്ല നീയെന്നു. നീ എന്താണെന്ന് കണ്ടെത്തുക.',
    'യഥാർത്ഥം മരിക്കില്ല, അസത്യമായത് ഒരിക്കലും ജീവിച്ചിരുന്നില്ല.',
    'ജ്ഞാനം എന്നെ ഒന്നുമല്ലെന്ന് പറയുന്നു. സ്നേഹം എന്നെ എല്ലാം ആണെന്ന് പറയുന്നു. ഈ രണ്ടിനിടയിലൂടെ എന്റെ ജീവിതം ഒഴുകുന്നു.',
    'നീ പരമ സത്യമാണ്. ചെറുതായി ചിന്തിക്കരുത്.',
    'നിങ്ങൾ എന്താണെന്ന് അറിയാൻ, ആദ്യം നിങ്ങൾ എന്തല്ലെന്ന് അന്വേഷിച്ച് അറിയണം.',
    'നിനക്കുള്ള ചൈതന്യം, എനിക്കുള്ള ചൈതന്യം, പ്രഥകമായി തോന്നുന്നവ, യഥാർത്ഥത്തിൽ ഒന്നാണ്; ആ ഏകത്വത്തെ തേടുക, അതാണ് സ്നേഹം.',
    'നിങ്ങളെ സ്വയം നിർവചിക്കാനുള്ള പ്രവണത ഒഴിവാക്കുക മാത്രമാണ് നിങ്ങൾക്കാവശ്യം.',
    'നിങ്ങൾക്ക് വഴി തന്നെയാണ് ലക്ഷ്യം എന്ന് തിരിച്ചറിയുമ്പോഴും, നിങ്ങൾ എപ്പോഴും ലക്ഷ്യത്തിലെത്താനല്ല, അതിന്റെ സൗന്ദര്യവും ജ്ഞാനവും ആസ്വദിക്കാനാണ് വഴിയിലിരിക്കുന്നതെന്ന് മനസ്സിലാകുമ്പോഴും, ജീവിതം ഒരു ചുമതലയായി നിൽക്കാതെ സ്വാഭാവികവും ലളിതവുമാകുന്നു.',
    'നീ ശരീരം അല്ല. നീ മനസ്സും അല്ല. നീ അവ രണ്ടും പ്രത്യക്ഷപ്പെടുന്ന ജാഗ്രതയാണ്.',
    'നിങ്ങളുടെ യഥാർത്ഥ സ്വഭാവത്തെ അറിയുന്ന നിമിഷം, നിങ്ങൾക്ക് ഒന്നിനും ഭയം ഉണ്ടാകില്ല.',
    'നിങ്ങൾ ഈ അല്ലെങ്കിൽ ആ കാര്യങ്ങൾ ചെയ്യുകയോ ആകുകയോ ചെയ്യുന്നതായി ചിന്തിക്കുന്നത് നിർത്തുക, നിങ്ങൾ എല്ലാത്തിന്റെയും ഉറവിടവും ഹൃദയവുമാണെന്ന് ബോധ്യമായിരിക്കും.',
    'നീ കാണുന്ന ഒന്നും നിനക്കു സ്വന്തമല്ല. നീ കാണുന്ന ഒന്നും നിനക്കുമായി ബന്ധപ്പെട്ടതല്ല.',
    'പരമ്പരാഗത മാനദണ്ഡങ്ങളെ ഉപേക്ഷിക്കുക. അവയെ പരമ്പരാഗതത്വത്തിന്റെ അനുയായികൾക്ക് വിട്ടുകൊടുക്കുക.',
    'നിന്റെ യഥാർത്ഥ ഭവനം ശൂന്യതയിലാണ്, എല്ലാ ഉള്ളടക്കങ്ങളുടെയും ശൂന്യതയിൽ.',
    'ഞാൻ അകത്തെക്കാൾ നോക്കുമ്പോൾ ഞാൻ ഒന്നുമല്ലെന്ന് കാണുമ്പോൾ, അതാണ് ജ്ഞാനം. ഞാൻ പുറത്തേക്ക് നോക്കുമ്പോൾ ഞാൻ എല്ലാം ആണെന്ന് കാണുമ്പോൾ, അതാണ് സ്നേഹം.',
    'മനം അഗാധതയെ സൃഷ്ടിക്കുന്നു, ഹൃദയം അതിനെ കടക്കുന്നു.',
    'നീ എന്താണെന്ന് കരുതുന്നുവോ, അതല്ല നീ.',
    'നീ ഒരു വ്യക്തിയെന്നു കരുതുന്നു, പക്ഷേ നീ ഒരിക്കലും വ്യക്തിയായി ജനിച്ചിട്ടില്ല.',
    'വാസ്തവത്തിൽ, നിങ്ങൾ ഒരു വസ്തുവല്ല, മറ്റ് വസ്തുക്കളിൽ നിന്ന് വേർപെട്ടതുമല്ല.',
    'യാഥാർത്ഥ്യത്തെ തേടുന്ന ശ്രമം ഏറ്റവും അപകടകരമായ സംരംഭമാണ്, കാരണം അത് നിങ്ങൾ ജീവിക്കുന്ന ലോകത്തെ നശിപ്പിക്കുന്നു.',
    'എല്ലാ വേർപാടുകളും, ഏത് തരത്തിലുള്ള അന്യത്വവും അകലംവുമെല്ലാം അസത്യമാണ്.',
    'നീയാണ് ആ പരമാവധി സാധ്യത, അതിന്റെ സമഗ്രമായ ചൈതന്യം പ്രകടനവും പ്രകടനവുമാണ്.',
    'വ്യക്തിഗതത്വത്തിന് സംരക്ഷണം ആവശ്യമുണ്ട്, യഥാർത്ഥതയ്ക്ക് സംരക്ഷണം ആവശ്യമില്ല.',
    'നിങ്ങളുടെ സ്വന്തം കൽപ്പന മാത്രമേ നിങ്ങളെ അലട്ടാൻ കഴിയൂ.',
    'നിങ്ങളുടെ സ്വന്തം ഭാവന മാത്രമേ നിങ്ങളെ അലട്ടാൻ കഴിയൂ എന്ന് നിങ്ങൾക്ക് ഉറപ്പായാൽ, നിങ്ങളുടെ ആഗ്രഹങ്ങളെയും ഭയങ്ങളെയും അവഗണിക്കാൻ നിങ്ങൾക്ക് കഴിയും.',
    'നീ ലോകത്തിൽ അല്ല, ലോകം നിന്റെ ഉള്ളിലാണ്.',
    '"ഞാൻ" എന്ന അനുഭവം നിങ്ങളുടെ സ്വന്തംതാണ്. നിങ്ങൾക്ക് അതിൽ നിന്ന് വേർപിരിയാൻ കഴിയില്ല, പക്ഷേ "ഞാൻ യുവാവാണ്", "ഞാൻ സമ്പന്നനാണ്" എന്നിങ്ങനെ ഏതെങ്കിലും കാര്യങ്ങളുമായി അതിനെ ബന്ധിപ്പിക്കാനാകുന്നു.',
    'വേദനയും ആനന്ദവും എന്ന രണ്ടു കരകളുടെ ഇടയിൽ ജീവിതത്തിന്റെ നദി ഒഴുകുന്നു. മനസ്സ് ജീവിതത്തോടൊപ്പം ഒഴുകാൻ വിസമ്മതിച്ച് കരകളിൽ കുടുങ്ങുമ്പോഴാണ് അത് ഒരു പ്രശ്നമാകുന്നത്.',
    'സ്വാതന്ത്ര്യം അറിയപ്പെടുന്നതിൽ നിന്ന് ആണ്.',
    'നീ ജനിച്ചുവന്ന ലോകത്തിൽ നിന്നുള്ളതാണെന്ന് വിശ്വസിക്കുന്നതുകൊണ്ടാണ് നിന്റെ ദൗർബല്യം.',
    'മോക്ഷത്തിനായി മനസ്സിനെ ആശ്രയിക്കരുത്. നിങ്ങളെ ബന്ധനത്തിലാക്കിയത് മനസ്സാണ്.',
    'യഥാർത്ഥ ഗുരു ജീവിതം തന്നെയാണ്.',
    'നീ അതിനെ തേടേണ്ടതില്ല, കാരണം നീ തന്നെയാണ് അത്.',
    'സ്നേഹം പറയുന്നു \'ഞാൻ എല്ലാം ആണ്\'. ജ്ഞാനം പറയുന്നു \'ഞാൻ ഒന്നുമല്ല\'. ഈ രണ്ടിനും ഇടയിൽ, എന്റെ ജീവിതം ഒഴുകുന്നു.',
    'മനസ്സ്, ആത്മാവ്, ആത്മാവുൾപ്പെടുന്ന ത്രിത്വം ആലോചിക്കുമ്പോൾ ഏകത്വമാകുന്നു.',
    'മാത്രം ഇരിക്കുക. നിങ്ങളുടെ യഥാർത്ഥ സ്വഭാവം ഉദിക്കട്ടെ. അന്വേഷിച്ച് മനസ്സിനെ അലട്ടരുത്.',
    'നിങ്ങളുടെ ആത്മാവാണ് നിങ്ങളുടെ പരമ ഗുരു. ബാഹ്യ ഗുരു ഒരു മൈൽക്കല്ല് മാത്രമാണ്.',
    'നിങ്ങളുടെ ലോകത്ത് എല്ലാത്തിനും ഒരു ആരംഭവും ഒരു അവസാനവും വേണം. അത് ഇല്ലെങ്കിൽ, നിങ്ങൾ അതിനെ നിത്യമായെന്ന് വിളിക്കുന്നു.',
    'സാക്ഷാത്കാരമുള്ള വ്യക്തി ലോകത്തെ അതിന്റെ യഥാർത്ഥ രൂപത്തിൽ കാണുന്നു: സ്വഭാവത്തിൽ ഏകമെങ്കിലും രൂപത്തിൽ വൈവിധ്യമുള്ളത്.',
    'കൽപ്പനകളില്ലാതെ നോക്കാനും, വക്രതകളില്ലാതെ കേൾക്കാനും പഠിക്കുക.',
    'മനസ്സാണ് മനസ്സ് ഉണ്ടെന്ന് നിങ്ങളോട് പറയുന്നത്. അതിൽ ചതിയപ്പെടരുത്.',
    'സത്യം നല്ല പെരുമാറ്റത്തിന് ലഭിക്കുന്ന പ്രതിഫലമല്ല, അല്ലെങ്കിൽ ചില പരീക്ഷണങ്ങൾ വിജയിച്ചാൽ ലഭിക്കുന്ന സമ്മാനവുമല്ല.',
    'നിനക്കു നീ മനുഷ്യനാണെന്ന് തോന്നിക്കുന്നത് മനുഷ്യൻ അല്ല.',
    'നീ സ്വയം ഒരു തടവറ നിർമ്മിക്കാൻ എത്ര ശക്തി ചെലവഴിച്ചുവോ, അത്രയും ശക്തി അത് പൊളിക്കാൻ ചെലവഴിക്കുക.',
    'നീ വ്യക്തിയല്ലെന്ന് മനസ്സിലാക്കാൻ, ആ വ്യക്തിയെ നിരീക്ഷിക്കുക. ആ വ്യക്തിയെ ബോധത്തിൽ ഒരു വസ്തുവായി കാണുക.',
    'ശരീര-മനസ്സിന്റെ തിരിച്ചറിയൽ വിട്ട് കളയുന്നതിൽ എന്താണ് പ്രയാസം? ഒടുവിൽ, നിങ്ങൾ ശരീര-മനസ്സല്ലല്ലോ.',
    'നീ സ്വയം അറിയാത്തതിനാൽ മരണം ഭയപ്പെടുന്നു. യഥാർത്ഥ നീ അജരാമരമാണ്.',
    'നിനക്കു നിന്നെ എല്ലാം എന്നും അതീതവും ആയി അറിയാൻ തടസ്സം സൃഷ്ടിക്കുന്നത് ഓർമ്മയിൽ അധിഷ്ഠിതമായ മനസ്സാണ്.',
    'മനസ്സ് കാലത്തിനുള്ളിൽ നിലനിൽക്കുന്നു, എന്നാൽ നാം കാലാതീതരാണ്.',
    'നിങ്ങൾ തന്നെയാണ് പ്രേമം - നിങ്ങൾക്ക് ഭയം ഇല്ലാത്തപ്പോൾ.',
    'നിങ്ങൾ സ്വയം കരുതുന്നത് നിങ്ങൾ അല്ല. നിങ്ങൾ ശരീരമല്ല, മനസ്സല്ല, വ്യക്തിത്വബോധവുമല്ല. ഈ എല്ലാം പ്രത്യക്ഷപ്പെടുകയും അപ്രത്യക്ഷമാകുകയും ചെയ്യുന്ന നിത്യചൈതന്യം നിങ്ങൾ ആണ്.',
    'നിങ്ങളെ വ്യക്തിയായി അല്ല, ബോധമായി അറിയുന്ന നിമിഷം, എല്ലാ ദുഃഖങ്ങളും അവസാനിക്കുന്നു. അവശേഷിക്കുന്നത് അനുഭവമല്ല, നിങ്ങളുടെ സ്വാഭാവികാവസ്ഥയായ സമാധാനമാണ്.',
    'ശരീരം ഉണ്ടായതിനു മുമ്പും ലോകം പ്രത്യക്ഷമായതിനു മുമ്പും നീ ഉണ്ടായിരുന്നുവല്ലോ. എല്ലാ ആശയങ്ങളുടെയും മുമ്പിലുള്ള ആ സാന്നിധ്യത്തിൽ നിലകൊള്ളുക, മറ്റെല്ലാം വിട്ടുകളയുക.',
    '\'ഞാൻ\' എന്നത് ആദ്യ വാതിലാണ്. അതിനൊപ്പം സ്ഥിരമായി ഇരിക്കുക. \'ഞാൻ\' പോലും ലയിച്ചുപോകുമ്പോൾ, പരമസത്യം മാത്രം ശേഷിക്കുന്നു.',
    'നീ ലോകത്തിൽ അല്ല; ലോകം നിന്നിൽ ആണ്. നീ നിന്റെ ബോധത്തിൽ മുഴുവൻ ബ്രഹ്മാണ്ഡവും വഹിക്കുന്നു.',
    'നിങ്ങൾ ആരാണെന്ന് അറിയാൻ, ആദ്യം നിങ്ങൾ അല്ലാത്തത് അന്വേഷിക്കണം. കാണപ്പെടുന്നതും അനുഭവപ്പെടുന്നതും അനുഭവപ്പെടുന്നതും നിങ്ങൾ അല്ല.',
    'യഥാർത്ഥ ആത്മാവ് പ്രാപിക്കേണ്ട ഒന്നല്ല. നിങ്ങൾക്കുറിച്ചുള്ള എല്ലാ തെറ്റായ ധാരണകളും ഉപേക്ഷിക്കുമ്പോൾ നിങ്ങൾ ആകുന്നത് അതാണ്.',
    'നിങ്ങൾ നിങ്ങളെ പരിമിതമായവനായി കരുതുന്നു, ആ പരിമിതിയുടെ ഫലമായി നിങ്ങൾ ദുഃഖിക്കുന്നു. യാഥാർത്ഥ്യത്തിൽ, നിങ്ങൾക്ക് യാതൊരു അതിരും ഇല്ല.',
    'ശരീര-മനസ്സുമായി ഐക്യം നിർത്തുമ്പോൾ, നിങ്ങൾ ഒരിക്കലും ബന്ധിതരായിരുന്നില്ല, ഒരിക്കലും പ്രശ്നത്തിൽപ്പെട്ടിരുന്നില്ല, ഒരിക്കലും അപൂർണ്ണരായിരുന്നില്ലെന്ന് കണ്ടെത്തുന്നു.',
    'അവബോധം വ്യക്തിപരമായതല്ല. വ്യക്തി അവബോധത്തിൽ പ്രത്യക്ഷപ്പെടുന്നു, പക്ഷേ അവബോധം വ്യക്തിക്ക് സ്വന്തമായതല്ല.',
    'ചൈതന്യം താത്കാലികമായ അവസ്ഥയാണ്. അത് പ്രത്യക്ഷപ്പെടുകയും അപ്രത്യക്ഷമാകുകയും ചെയ്യുന്നു. ചൈതന്യത്തെ അറിയുന്ന അതിനെ അതീതമാണ്.',
    'പരമാത്മാവ് സ്വയം ബോധവാനല്ല. ബോധം എന്നത് പരമാത്മാവിൽ ഉദയിക്കുന്ന ഒരു പ്രതിഭാസമാണ്, സമുദ്രത്തിലെ ഒരു തിരമാല പോലെ.',
    'നീ ചൈതന്യത്തെ നിനക്കു തന്നെയെന്ന് കരുതുന്നു, പക്ഷേ ചൈതന്യം പോലും നിരീക്ഷിക്കപ്പെടുന്നു. ചൈതന്യത്തെ അറിയുന്ന അതിനെ കണ്ടെത്തുക.',
    'ശരീരവും ലോകവും ചൈതന്യത്തോടൊപ്പം ഉദിക്കുന്നു. ചൈതന്യം ഇല്ലാത്തപ്പോൾ ലോകവും ഇല്ല.',
    'ചേതനയേക്കാൾ മുമ്പ് അനുഭവമോ, സമയമോ, സ്ഥലമോ ഇല്ല — എന്നാൽ നിങ്ങൾ ഉണ്ടായിരുന്നു. അതാണ് നിങ്ങളുടെ യഥാർത്ഥ സ്വഭാവം.',
    'ചൈതന്യം ശരീരത്തിൽ ആശ്രയിക്കുന്നു, എന്നാൽ പരമാർത്ഥം ഒന്നിലും ആശ്രയിക്കുന്നില്ല. വ്യത്യാസം അറിയുക.',
    'മരണത്തിൽ ചൈതന്യം ലയിക്കുമ്പോൾ, നിങ്ങൾ യഥാർത്ഥത്തിൽ ആകുന്നത് മരിക്കില്ല, കാരണം അത് ഒരിക്കലും ജനിച്ചിട്ടില്ല.',
    'പരമസത്യം വാക്കുകളിൽ വിവരിക്കാനാകില്ല. പറയുന്നതെന്തും ചൈതന്യത്തെക്കുറിച്ചാണ്.',
    'ചേതനയുടെ ഉറവിടത്തിൽ നിലകൊള്ളുക, നിങ്ങൾ അതിനെ അതിക്രമിക്കും.',
    'നിങ്ങൾ ബോധത്തിന്റെ ചലനത്തെ യാഥാർത്ഥ്യമായി തെറ്റിദ്ധരിക്കുന്നു. യാഥാർത്ഥ്യം ചലിക്കാത്തതാണ്.',
    'നിന്റെ ഏക സാധനയാണ് \'ഞാൻ\' എന്ന ബോധത്തെ പിടിച്ചു നിർത്തുകയും മറ്റെല്ലാം അഹംകാരമല്ലെന്ന് തള്ളുകയും ചെയ്യുക.',
    'പ്രത്യക്ഷമായത് മാറ്റാൻ ശ്രമിക്കരുത്. നിങ്ങൾ ആരാണെന്ന് മനസിലാക്കുക, പിന്നെ എല്ലാം സ്വയം മാറും.',
    'ശ്രമം ആവശ്യമാണ്, ശ്രമരഹിതത്വം കണ്ടെത്തുന്നതുവരെ. പിന്നെ ശ്രമം പോലും വിട്ടുപോകുന്നു.',
    'സ്വയം അന്വേഷിക്കൽ ഒരു മാനസിക വ്യായാമമല്ല. അത് പ്രത്യക്ഷപ്പെടുന്ന ഏതു കാര്യത്തോടും ഐക്യപ്പെടാൻ നിരന്തരം നിഷേധിക്കുന്നതാണിത്.',
    'നീ ആകാശത്ത് ഒഴുകുന്ന മേഘങ്ങളെ പോലെ നിന്റെ ചിന്തകളെ നിരീക്ഷിക്കൂ. അവയെ നിന്റെതെന്നു അവകാശപ്പെടരുത്.',
    'മനസ്സിനെ അതിജീവിക്കാൻ മനസ്സിന് സഹായം ചെയ്യാനാവില്ല. അതിനെ മനസ്സിലാക്കി അതിനപ്പുറം പോകേണ്ടത് നിങ്ങൾ തന്നെയാണ്.',
    'നിങ്ങൾ മനസ്സിനെ നിരീക്ഷിക്കുമ്പോൾ, നിങ്ങൾ ഇതിനകം അതിനപ്പുറത്താണ്.',
    'എത്ര സമയം എടുക്കും എന്ന് ചോദിക്കേണ്ട. നിങ്ങളുടെ അന്വേഷണത്തിൽ ആഗ്രഹവും സത്യസന്ധതയും നിലനിർത്തുക.',
    'നിന്റെ മനസ്സിനെ ശുദ്ധീകരിക്കേണ്ടതില്ല. അതുമായി ഐക്യപ്പെടുന്നത് നിർത്തുക.',
    'നിശ്ശബ്ദത എന്നത് ശബ്ദത്തിന്റെ അഭാവമല്ല; അത് തിരിച്ചറിയലിന്റെ അഭാവമാണ്.',
    'ഒരു വ്യക്തി ഓർമ്മകളുടെയും ശീലങ്ങളുടെയും ശിക്ഷണത്തിന്റെയും സമാഹാരമാണ്. നിങ്ങൾ ആ സമാഹാരമല്ല.',
    'അഹങ്കാരം ഒരു ആശയമാണ് — ചൈതന്യം സ്വീകരിച്ച ഒരു തെറ്റായ കേന്ദ്രം.',
    'നിങ്ങൾ \'ഞാൻ ദുഃഖിക്കുന്നു\' എന്ന് പറയുമ്പോൾ, ഈ \'ഞാൻ\' ആരാണെന്ന് അന്വേഷിക്കുക. നിങ്ങൾക്ക് അത് കണ്ടെത്താനാവില്ല.',
    '\'ഞാനാണ് ചെയ്യുന്നത്\' എന്ന ധാരണയാണ് ബന്ധനം. അത് പോയാൽ, സ്വാതന്ത്ര്യം ഉണ്ടാകും.',
    'വ്യക്തിത്വം യാഥാർത്ഥ്യമല്ല; അത് ബോധം ധരിക്കുന്ന ഒരു മുഖാവരണം മാത്രമാണ്.',
    'നീ സ്വയം ഒരു വ്യക്തിയെന്നു കരുതുന്നിടത്തോളം നീ ഭയത്തിൽ ജീവിക്കും.',
    'ശരീരത്തോടൊപ്പം വ്യക്തിത്വബോധം ഉണ്ടാകുന്നു, അത് ശരീരത്തോടൊപ്പം അവസാനിക്കുന്നു.',
    'നിങ്ങൾ ആ വ്യക്തിയെ പിടിച്ചുപറ്റുന്നത് ശൂന്യതയെ പേടിക്കുന്നതിനാലാണ്, പക്ഷേ ആ ശൂന്യതയാണ് സമാധാനം.',
    'വ്യക്തി ലയിച്ചാൽ ശേഷിക്കുന്നത് ശൂന്യതയല്ല, പൂർണ്ണതയാണ്.',
    'അഹങ്കാരം തുടർച്ചയെ ആഗ്രഹിക്കുന്നു; യാഥാർത്ഥ്യത്തിന് അതില്ല.',
    'എല്ലാ ദുഖങ്ങളും തിരിച്ചറിയലിൽ നിന്നാണ് ജനിക്കുന്നത്. നാശവന്തമായതിനെ താങ്കളെന്നു കരുതുന്നതിനാൽ നിങ്ങൾ ദുഃഖിക്കുന്നു.',
    'അപൂർണ്ണതയുടെ ഭാവത്തിൽ നിന്നാണ് ആഗ്രഹം ഉദിക്കുന്നത്, അതു തന്നെ അസത്യമാണ്.',
    'ഭയം വ്യക്തിയ്ക്ക് മാത്രമേ ഉള്ളൂ. ആത്മാവിന് ഭയം അറിയില്ല.',
    'നീ ശരീരം അല്ലെന്ന് അറിയുമ്പോൾ, മരണം ഭയപ്പെടുത്തുന്നത് അവസാനിക്കുന്നു.',
    'വേദന ശരീരപരമാണ്; ദുരിതം മാനസികമാണ്. മനസ്സിലാക്കുന്നതിലൂടെ നിങ്ങൾക്ക് ദുരിതത്തെ അതിജീവിക്കാം.',
    'നിങ്ങൾ എതിർക്കുന്നതു നിലനിൽക്കും. നിങ്ങൾ മനസ്സിലാക്കുന്നതു ലയിക്കും.',
    'ആഗ്രഹം എന്നത് ഭാവിയിൽ പ്രതിഫലിക്കുന്ന സ്മരണം ആണ്.',
    'സ്വാതന്ത്ര്യം ആഗ്രഹങ്ങളുടെ നിറവേറ്റലല്ല, മറിച്ച് ആഗ്രഹങ്ങളിൽ നിന്ന് മോചനം.',
    'വേദന നിങ്ങളെക്കുറിച്ച് നിങ്ങൾ തെറ്റിദ്ധരിച്ചിരിക്കുകയാണെന്ന് സൂചിപ്പിക്കുന്ന ഒരു സന്ദേശമാണ്.',
    'തെറ്റായ തിരിച്ചറിവ് അവസാനിക്കുമ്പോൾ, അതിനൊപ്പം ദുഖവും അവസാനിക്കുന്നു.',
    'ലോകം അസത്യമല്ല, പക്ഷേ നിങ്ങൾ ചിന്തിക്കുന്നതു പോലെ അതല്ല. അത് ചൈതന്യത്തിന്റെ പ്രതിഫലനമാണ്.',
    'ലോകം യഥാർത്ഥമെന്ന് തോന്നുന്നത്, നിങ്ങൾ അതിന്റെ ഭാഗമാണെന്ന് വിശ്വസിക്കുന്നതിനാലാണ്.',
    'ചേതന ശാന്തമായിരിക്കുമ്പോൾ ലോകവും ശാന്തമാണ്.',
    'ഭൂമണ്ഡലം അവബോധിക്കപ്പെടുന്നിടത്തോളം മാത്രം നിലനിൽക്കുന്നു.',
    'നീ വ്യക്തിപരമായി സ്വീകരിക്കുമ്പോൾ ലോകത്തിന് യാഥാർത്ഥ്യം നൽകുന്നു.',
    'ലോകത്തിന് ബോധത്തെ വിട്ട് സ്വതന്ത്രമായ നിലനിൽപ്പ് ഇല്ല.',
    'യാഥാർത്ഥ്യം സരളമാണ്; മായികത സങ്കീർണ്ണമാണ്.',
    'ലോകം നല്ലതോ ചീത്തയോ അല്ല. അത് നിങ്ങളുടെ ബോധത്തെ മാത്രമേ പ്രതിഫലിപ്പിക്കുന്നുള്ളു.',
    'നിങ്ങൾ \'യഥാർത്ഥ ജീവിതം\' എന്ന് വിളിക്കുന്നത് അനുഭവങ്ങളുടെ ഒരു പ്രവാഹമാണ്.',
    'ലോകം ഒരു നാടകമാണ്, എന്നാൽ ചൈതന്യം അതിനെ ഗൗരവത്തോടെ കാണുന്നു.',
    'ഗുരു നിങ്ങൾക്ക് പുതിയതായി ഒന്നും നൽകുന്നില്ല. അദ്ദേഹം തെറ്റായതിനെ നീക്കുന്നു.',
    'കൃപ ഒരു സംഭവമല്ല; അത് നിങ്ങളുടെ സ്വഭാവമാണ്.',
    'നിങ്ങൾ തയ്യാറായപ്പോൾ, ഉപദേശം നിങ്ങളെ കണ്ടെത്തും.',
    'ഗുരു വഴി കാണിക്കുന്നു, പക്ഷേ നിങ്ങൾ തന്നെ കാണണം.',
    'ആ ഉപദേശം നിങ്ങളുടേതായി സ്ഥിരീകരിക്കുന്നതുവരെ വിശ്വസിക്കുക.',
    'ഗുരുവിൽ ഉള്ള വിശ്വാസം നിങ്ങളുടെ സ്വയം ഉള്ള ആത്മവിശ്വാസമാണ്.',
    'വാക്കുകൾ വെറും സൂചനകളാണ്. അവയിൽ പിടിച്ചു നിൽക്കരുത്.',
    'മഹത്തായ ഉപദേശം മൗനമാണ്.',
    'ഒരു സത്യാധ്യാപകൻ അഹങ്കാരത്തെ ആശ്വസിപ്പിക്കുകയല്ല; അത് നശിപ്പിക്കുകയാണ്.',
    'ആത്മാവബോധം സമ്പൂർണ്ണമായപ്പോൾ ഗുരു അപ്രത്യക്ഷനാവുന്നു.',
    'മോക്ഷം കാലത്തിനുള്ളിലെ ഒരു നേട്ടമല്ല. അത് കാലാതീതമായതിന്റെ തിരിച്ചറിവാണ്.',
    'നീ ഇപ്പോൾ സ്വതന്ത്രനാണ്, പക്ഷേ നീ നിന്നെ ബന്ധിതനായി കരുതുന്നു.',
    'സ്വാതന്ത്ര്യം നിങ്ങൾ ഇഷ്ടപ്പെടുന്നതു ചെയ്യുന്നതല്ല, എന്നാൽ ആഗ്രഹത്തിൽ നിന്ന് നിർബന്ധിതരാകാതിരിക്കുക എന്നതാണ്.',
    'എന്നെന്നില്ലാത്തപ്പോൾ, ബന്ധനമില്ല.',
    'മോക്ഷം ആണ് അന്വേഷത്തിന്റെ അന്ത്യം.',
    'മുക്തനായി നിലകൊള്ളുന്നവനോട് ഒന്നും സംഭവിക്കുകയില്ല, കാരണം സംഭവിക്കാൻ ആരുമില്ല.',
    'മുക്തി അവസ്ഥ സാധാരണവും സ്വാഭാവികവും ശ്രദ്ധിക്കപ്പെടാത്തതുമാണ്.',
    'നിങ്ങൾ സ്വതന്ത്രനാകുന്നില്ല; നിങ്ങൾ ഒരിക്കലും ബന്ധിതനല്ലായിരുന്നു എന്ന് കണ്ടെത്തുന്നു.',
    'ഊന്നതമായ അവസ്ഥ ഒരു അവസ്ഥയല്ല.',
    'അജ്ഞാനം അവസാനിക്കുമ്പോൾ, പ്രത്യേകമായി ഒന്നും സംഭവിക്കുന്നില്ല — സത്യം വെളിച്ചത്തിൽ പ്രത്യക്ഷമാകുന്നു.',
    'നീ യാഥാർത്ഥ്യത്തിന്റെ ഒരു ഭാഗമല്ല. നീ തന്നെ യാഥാർത്ഥ്യം.',
    'എന്തും പ്രത്യക്ഷമാകുന്നത് അപ്രത്യക്ഷമാകേണ്ടതാണ്. പ്രത്യക്ഷമാകാത്തത് അപ്രത്യക്ഷമാകാൻ കഴിയില്ല.',
    'പരമാത്മാവിന് ഗുണങ്ങളൊന്നുമില്ല, എങ്കിലും എല്ലാ ഗുണങ്ങളും അതിൽ നിന്നാണ് ഉദ്ഭവിക്കുന്നത്.',
    'നീ സ്വയം ആ ആത്യന്തികതയാണ്, അതിനെ ഒരു വസ്തുവായി അറിയാൻ കഴിയില്ല.',
    'ആത്മാവ് അനുഭവപ്പെടുന്നതല്ല; അത് അനുഭവിക്കുന്നതാണു.',
    'എല്ലാ ചോദ്യങ്ങളും അവസാനിക്കുമ്പോൾ, സത്യം നിലനിൽക്കും.',
    'നിങ്ങളിൽ ഒന്നും ചേർക്കേണ്ടതില്ല; തെറ്റായ ധാരണകൾ മാത്രം നീക്കം ചെയ്യണം.',
    'നിങ്ങളുടെ യഥാർത്ഥ സ്വഭാവം അംഗീകരണത്തിനും നിഷേധത്തിനും അതീതമാണ്.',
    'ശാന്തമായി ഇരിക്കുക, നോക്കുക — അത്രയേ ഉള്ളു.',
    'സത്യം ലളിതമാണ്, പക്ഷേ മനസ്സ് ലാളിത്യത്തെ എതിര്‍ക്കുന്നു.',
    'ആത്മാവിന്റെ സാന്നിധ്യത്തിൽ നിലകൊള്ളുക, അതും ലയിക്കുന്നതുവരെ.',
    'സത്യത്തെ പിടിക്കാൻ ശ്രമിക്കരുത്; അസത്യത്തെ വിട്ടുപോകാൻ അനുവദിക്കുക.',
    'അവബോധമാണ് മുഖ്യം, അനുഭവമല്ല.',
    'യഥാർത്ഥം എന്നും സന്നിഹിതമാണ്.',
    'നീ കാലത്തിനുമുമ്പുള്ളവൻ.',
    'യാഥാർത്ഥ്യത്തിൽ തെറ്റൊന്നുമില്ല; നിങ്ങളുടെ ആശയങ്ങളാണ് തെറ്റായിരിക്കുന്നത്.',
    'ആത്മാന്വേഷണം അപ്രത്യക്ഷമാകുമ്പോൾ, അന്വേഷിച്ചതു വെളിപ്പെടുന്നു.',
    'ധാരണകളിൽ നിന്ന് ശൂന്യമാകുക.',
    'നീ ദൃക്‌ഷി, ദൃശ്യമായതല്ല.',
    'നീ ഉള്ളവൻ ആണല്ലോ — അതു മതി.',
  ],

  [
    Article(
        heading: 'ഞാൻ ആരാണ്? - അടിസ്ഥാനപരമായ ചോദ്യം',
        body: 'നിസർഗദത്ത മഹാരാജിന്റെ ഉപദേശം "ഞാൻ ആരാണ്?" എന്ന അടിസ്ഥാന ചോദ്യത്തെ ചുറ്റിപ്പറ്റിയാണ്. അദ്ദേഹം തന്റെ ശിഷ്യരെ എല്ലാ ആശയങ്ങളും തിരിച്ചറിവുകളും മറികടന്ന് അവരുടെ യഥാർത്ഥ സ്വഭാവം അന്വേഷിക്കാൻ നിരന്തരം പ്രേരിപ്പിക്കുകയായിരുന്നു. \n\n"നിങ്ങൾ നിങ്ങളെ നിങ്ങൾ കരുതുന്നവരല്ല," അദ്ദേഹം പറയാറുണ്ടായിരുന്നു. "നിങ്ങൾ എന്താണെന്ന് കണ്ടെത്തുക." ഈ അന്വേഷണമാണ് ബുദ്ധിമുട്ടുള്ള ഒരു വ്യായാമം അല്ല, \'ഞാൻ\' അനുഭവത്തിന്റെ ഉറവിടത്തിലേക്ക് നേരിട്ടുള്ള അന്വേഷണമാണിത്.\n\nമഹാരാജ് നമ്മൾ ശരീരം, മനസ്സ്, ചിന്തകൾ, വികാരങ്ങൾ, ജീവിതത്തിൽ നാം വഹിക്കുന്ന വിവിധ വേഷങ്ങൾ എന്നിവയുമായി പതിവായി തിരിച്ചറിവ് ചെയ്യുന്നതായി പഠിപ്പിച്ചു. എന്നാൽ ഇവയൊക്കെ ബോധത്തിൽ പ്രത്യക്ഷപ്പെടുന്ന വസ്തുക്കളാണ്. നാം അവിടെ പ്രത്യക്ഷപ്പെടുന്ന സാക്ഷിത്വമാണ്, അവയുടെ വസ്തുക്കളല്ല.\\n\\nസ്വയം അന്വേഷിക്കുന്ന പ്രക്രിയയിൽ, നിങ്ങൾ അല്ലാത്തതെല്ലാം നിഷേധിക്കേണ്ടതാണ് - "ഞാൻ ശരീരം അല്ല, ഞാൻ മനസ്സ് അല്ല, ഞാൻ ചിന്തകൾ അല്ല" - നിങ്ങൾ എന്താണ് അവശേഷിക്കുന്നത് എന്നതിലേക്ക് എത്തുന്നതുവരെ. അവശേഷിക്കുന്നത് ശുദ്ധമായ ബോധം, ശുദ്ധമായ സത്ത, നിങ്ങളുടെ യഥാർത്ഥ സ്വഭാവമാണ്.\\n\\n"നിങ്ങൾ എന്താണെന്ന് അറിയാൻ, നിങ്ങൾ ആദ്യം നിങ്ങൾ അല്ലാത്തതെന്താണെന്ന് അന്വേഷിക്കുകയും അറിയുകയും ചെയ്യണം" എന്ന് മഹാരാജ് ഊന്നി പറഞ്ഞു. ഈ ഒഴിവാക്കലിന്റെ പ്രക്രിയ നിങ്ങളുടെ അടിസ്ഥാന സ്വഭാവത്തെ ശുദ്ധമായ സാക്ഷിത്വമായി തിരിച്ചറിയുന്നതിലേക്ക് നയിക്കുന്നു, എല്ലാ ഗുണങ്ങളും പരിധികളും മീതെ.\\n\\n"ഞാൻ ആരാണ്?" എന്ന ചോദ്യത്തെ ശക്തമായ ആത്മാർത്ഥതയും സത്യസന്ധതയും കൊണ്ട് പിന്തുടരേണ്ടതാണ്. ഇത് ബുദ്ധിമുട്ടിൽ മാത്രം മനസ്സിലാക്കുന്നത് മതിയല്ല; നിങ്ങളുടെ ആസ്തിത്വത്തിന്റെ ഓരോ നിമിഷത്തിലും പരന്ന ഒരു ജീവൻ അന്വേഷണമാകണം, അതുവരെ വ്യത്യസ്ത വ്യക്തിയെന്ന തെറ്റായ അനുഭവം മുഴുവനായും പിരിഞ്ഞു പോകണം.'
    ),
    Article(
        heading: 'ചേതനയുടെ സ്വഭാവം',
        body: 'നിസർഗദത്ത മഹാരാജിന്റെ ബോധത്തെ വിശദീകരിക്കുന്നതിൽ ഒരു പ്രത്യേക രീതിയുണ്ടായിരുന്നു, അത് ആഴത്തിലുള്ളതും ആക്സസിബിള്‍ ആണും. അദ്ദേഹം വ്യക്തിഗത ബോധം (അദ്ദേഹം "ഞാൻ ആകുന്നു" എന്ന അനുഭവം എന്ന് വിളിച്ചിരിക്കുന്നു) എന്നതും എല്ലാ അനുഭവങ്ങൾക്കപ്പുറം ഉള്ള പരമ ബോധം എന്നതും തമ്മിൽ വ്യത്യാസം വരുത്തി. \n\n"ഞാൻ ആകുന്നു" എന്നത് ബോധത്തിലെ ആദ്യ ചലനമാണ്, എല്ലാ അനുഭവങ്ങൾക്കും ജന്മം നൽകുന്ന പ്രാഥമിക ആശയമാണ്. മഹാരാജ്, "ഞാൻ ഈ" അല്ലെങ്കിൽ "ഞാൻ ആ" പോലുള്ള അധികങ്ങൾ ഇല്ലാതെ ഈ ശുദ്ധമായ "ഞാൻ ആകുന്നു" അനുഭവത്തെ പിടിച്ചിരിക്കാൻ നമ്മൾ ശ്രമിക്കണം എന്ന് പഠിപ്പിച്ചു.\n\n"നിന്റെ ബോധവും എന്റെ ബോധവും, പുറമേ രണ്ടായി കാണപ്പെടുന്ന, ഒരുതന്നെയാണ്" അദ്ദേഹം പറയുമായിരുന്നു. ഈ മനസ്സിലാക്കൽ വേർപാട് എന്ന ഭ്രമത്തെ ലയിപ്പിച്ച്, എല്ലാ പ്രത്യക്ഷ വൈവിധ്യങ്ങളുടെ അടിസ്ഥാനം ആയ ഐക്യത്തെ വെളിപ്പെടുത്തുന്നു.\n\nമഹാരാജ് ബോധം മസ്തിഷ്കം അല്ലെങ്കിൽ ശരീരം വഴി ഉത്പാദിപ്പിക്കപ്പെടുന്നില്ല എന്ന് വിശദീകരിച്ചു. ശരീരംയും മസ്തിഷ്കവും ബോധത്തിൽ പ്രത്യക്ഷപ്പെടുന്നു. ബോധം വ്യക്തിഗതമല്ല; ഇത് സർവവ്യാപിയായതാണ്, നമ്മൾ വ്യക്തിഗത ബോധമായി കരുതുന്നതു ഈ സർവവ്യാപിയായ ബോധത്തിന്റെ ഒരു പ്രതിഫലനമാണ്. \n\nഅവസാന യാഥാർത്ഥ്യം ബോധത്തെക്കാളും മുകളിലാണ് - ബോധം പ്രത്യക്ഷപ്പെടുകയും അപ്രത്യക്ഷപ്പെടുകയും ചെയ്യുന്ന അവസ്ഥയാണ് ഇത്. ബോധത്തിനുമുമ്പെയും, ഉൽപത്തി-അനുഉൽപത്തി മുമ്പെയും, ഇത് നിങ്ങളുടെ യഥാർത്ഥ സ്വഭാവമാണ്. \n\n"നിങ്ങൾ പരമ യാഥാർത്ഥ്യമാണ്," മഹാരാജ് പ്രഖ്യാപിക്കും. "ചെറിയ മനസ്സുള്ളവനാകരുത്." ഈ പരമ യാഥാർത്ഥ്യം ഒരു വസ്തുവായി അറിയാൻ കഴിയില്ല, കാരണം നിങ്ങൾ തന്നെ അതാണ്. നിങ്ങൾ ആരെന്നു നിങ്ങൾ കരുതുന്ന എല്ലാ കാര്യങ്ങളുടെ ലയനം വഴി മാത്രമേ ഇത് തിരിച്ചറിയാൻ കഴിയൂ.'
    ),
    Article(
        heading: 'വ്യക്തിയുടെ മായാ',
        body: 'നിസർഗദത്ത മഹാരാജിന്റെ ഏറ്റവും വിപ്ലവകരമായ ഉപദേശങ്ങളിൽ ഒന്നാണ് വ്യക്തിയുടെ ഭ്രമാത്മക സ്വഭാവത്തെക്കുറിച്ചുള്ളത്. അദ്ദേഹം പറയുന്നത്: "നിങ്ങൾ നിങ്ങളെ ഒരു വ്യക്തിയായി കരുതുന്നു, പക്ഷേ നിങ്ങൾ ഒരിക്കലും വ്യക്തിയായി ജനിച്ചിട്ടില്ല." \n\nവ്യക്തി എന്നത് സ്മരണകൾ, ചിന്തകൾ, തിരിച്ചറിവുകളുടെ ഒരു സമാഹാരമാണ്, ഇത് ഒരു പ്രത്യക്ഷ തുടർച്ച സൃഷ്ടിക്കുന്നു. എന്നാൽ അടുത്തു പരിശോധിക്കുമ്പോൾ, വ്യക്തി എന്നറിയപ്പെടുന്ന ഒരു ഉറച്ച ഘടകം ഇല്ല. ഇത് ഒരു സിനിമ പോലെയാണ് - വ്യക്തിഗത ഫ്രെയിമുകൾ ചലനവും കഥയും സൃഷ്ടിക്കുന്ന ഭ്രമം. \n\nമഹാരാജ് പഠിപ്പിച്ചത്, വ്യക്തി ഒരു മാനസിക നിർമ്മിതിയാണ്, സ്വതന്ത്ര യാഥാർത്ഥ്യമില്ലാത്ത ആശയങ്ങളുടെ ഒരു കൂട്ടമാണ്. "നിങ്ങൾ എന്താണ് എന്ന് നിങ്ങൾ കരുതുന്നുവോ, നിങ്ങൾ അതല്ല," അദ്ദേഹം ഉറപ്പിക്കുമായിരുന്നു. നിങ്ങളുടെ (ചിന്തനം) ഉള്ളിൽ വ്യക്തി പ്രത്യക്ഷപ്പെടുന്നു, പക്ഷേ നിങ്ങൾ വ്യക്തി അല്ല. \n\nഈ ബോധവൽക്കരണം മോചിതമാക്കുന്നതാണ്, കാരണം വ്യക്തിയുടെ എല്ലാ പ്രശ്നങ്ങളും, പരിമിതികളും, ദു:ഖങ്ങളും ഭ്രാന്തമായവയാണ്. നിങ്ങൾ വ്യക്തി അല്ലെന്ന് തിരിച്ചറിയുമ്പോൾ, നിങ്ങൾ വ്യക്തിയുടെ വിധി, karma, ആചാരങ്ങൾ എന്നിവയിൽ നിന്ന് മോചിതനാകുന്നു.\n\n"നിങ്ങൾ കാണുന്ന ഒന്നും നിങ്ങളുടെ സ്വന്തം അല്ല. നിങ്ങൾ കാണുന്ന ഒന്നും നിങ്ങളുമായി ബന്ധപ്പെട്ടിട്ടില്ല," മഹാരാജ് പറയുമായിരുന്നു. ഇതിൽ ശരീരം, മനസ്സ്, ചിന്തകൾ, ഞങ്ങൾ സാധാരണയായി നമ്മുടെതെന്ന് കരുതുന്ന വികാരങ്ങൾ ഉൾപ്പെടുന്നു.\n\nനിങ്ങൾ വ്യക്തി അല്ല എന്ന തിരിച്ചറിവ് ഒരു തത്ത്വചിന്താ നിലയല്ല, എന്നാൽ earnest self-inquiry വഴി ലഭിക്കുന്ന നേരിയ ബോധവൽക്കരണമാണ്. ഈ തിരിച്ചറിവ് സ്ഥിരവും അസ്ഥിരമല്ലാത്തതുമായപ്പോൾ, നിങ്ങൾ നിങ്ങളുടെ യഥാർത്ഥ സ്വഭാവമായുള്ളതിൽ - ശുദ്ധമായ ബോധം, ശുദ്ധമായ ആസ്തിത്വം, എല്ലാ വ്യക്തിഗത പരിധികളെയും മറികടന്ന നിലയിൽ നിൽക്കുന്നു.'
    ),
    Article(
        heading: 'പ്രേമവും ജ്ഞാനവും - സത്യത്തിന്റെ രണ്ട് ചിറകുകൾ',
        body: 'നിസർഗദത്ത മഹാരാജ് തന്റെ പ്രശസ്തമായ വാചകത്തിൽ സാക്ഷാത്കാരത്തിന്റെ പരadoxയെ മനോഹരമായി പ്രകടിപ്പിച്ചു: "ജ്ഞാനം എന്നെ ഒന്നുമല്ല എന്ന് പറയുന്നു. പ്രേമം എന്നെ എല്ലാം ആണെന്ന് പറയുന്നു. ഈ രണ്ടിനിടയിൽ എന്റെ ജീവിതം ഒഴുകുന്നു."\n\nജ്ഞാനം നിങ്ങളുടെ യഥാർത്ഥ സ്വഭാവമായ ശുദ്ധമായ ബോധത്തെ തിരിച്ചറിയലാണ്, അതിന് ഗുണങ്ങൾ, രൂപം, ഗുണങ്ങൾ ഇല്ല - മനസ്സാൽ പിടിക്കാൻ കഴിയുന്ന ഒന്നുമല്ല. ഈ ദൃശ്യം നിന്നെ ശൂന്യമായ, എല്ലാ അനുഭവങ്ങളും പ്രത്യക്ഷപ്പെടുന്ന ശൂന്യമായ സ്ഥലം ആകുന്നു.\n\nപ്രേമം, മറിച്ച്, ഈ തന്നെ ബോധം പ്രത്യക്ഷപ്പെടുന്ന എല്ലാം എന്നതിന്റെ അടിസ്ഥാനമായ തിരിച്ചറിയലാണ്. നിങ്ങൾ ഒന്നിൽ നിന്നും വേർപെടുത്തപ്പെട്ടിട്ടില്ല; നിങ്ങൾ പലതായുള്ള ഒരു പ്രത്യക്ഷമായവനാണ്. ഇത് നിങ്ങളുടെ സ്വന്തം ആത്മാവായി എല്ലാ സൃഷ്ടിയെയും ഉൾക്കൊള്ളുന്ന പ്രേമമാണ്.\n\nഇവ പരസ്പരം വിരുദ്ധമായ സത്യങ്ങൾ അല്ല, പക്ഷേ ഒരേ സാക്ഷാത്കാരത്തിന്റെ രണ്ട് വശങ്ങളാണ്. അവകാശം ശൂന്യവും സമ്പൂർണ്ണവും, ഒന്നും എല്ലാം, ഉന്നതവും ആന്തരികവുമാണ്. \n\n"ഞാൻ എന്റെ ഉള്ളിൽ നോക്കുമ്പോൾ ഞാൻ ഒന്നുമല്ല എന്ന് കാണുന്നത് ജ്ഞാനം ആണ്. ഞാൻ പുറത്തു നോക്കുമ്പോൾ ഞാൻ എല്ലാം ആണെന്ന് കാണുന്നത് പ്രേമമാണ്," മഹാരാജ് വിശദീകരിച്ചു. ഈ ഇരട്ട തിരിച്ചറിവ് സമ്പൂർണ്ണമായ മനസ്സിലാക്കലിന്റെ അടയാളമാണ്.\n\nഈ മനസ്സിലാക്കലിൽ നിന്ന് ജീവിക്കുന്നത്, നിങ്ങളെ ഒന്നുമല്ല (നോ-തിംഗ്) എന്നറിയുന്നതിന്റെ സമാധാനത്തിൽ സ്ഥാപിതമായിരിക്കുകയാണ്, അതേസമയം നിങ്ങളുടെ സ്വന്തം പ്രത്യക്ഷമായ എല്ലാം പ്രേമിക്കുന്നതും ആണ്. ഇത് സാക്ഷാത്കൃതനായ സത്യത്തിന്റെ സ്വാഭാവിക അവസ്ഥയാണ് - സ്വയം ശൂന്യമായെങ്കിലും എല്ലാംക്കുള്ള പ്രേമത്തിൽ സമ്പൂർണ്ണമായ.'
    ),
    Article(
        heading: 'ജന്മവും മരണമും അതിക്രമിച്ച്',
        body: 'നിസർഗദത്ത മഹാരാജിന്റെ മരണംയും അമരത്വവും സംബന്ധിച്ച ഉപദേശങ്ങൾ അത്യന്തം ശക്തവും ആശ്വസകരവുമായിരുന്നു. "യാഥാർത്ഥ്യം മരിക്കുകയില്ല, അസത്യമായത് ഒരിക്കലും ജീവിച്ചിരുന്നില്ല," അദ്ദേഹം ഉറപ്പോടെ പറയാറുണ്ടായിരുന്നു.\n\nഅദ്ദേഹത്തിന്റെ ദൃശ്യം പ്രകാരം, ജനനം മരണം എന്നു നമ്മൾ വിളിക്കുന്നതെല്ലാം ബോധത്തിൽ ഉള്ള പ്രത്യക്ഷതകൾ മാത്രമാണ്, ഒരു സ്വപ്നത്തിലെ ദൃശ്യങ്ങൾ പോലെയാണ്. ശരീരം ജനിക്കുന്നു, മരിക്കുന്നു, എന്നാൽ നിങ്ങൾ - ശരീരം പ്രത്യക്ഷപ്പെടുന്ന ബോധം - ഒരിക്കലും ജനിച്ചിട്ടില്ല, അതിനാൽ നിങ്ങൾ മരിക്കാനാവില്ല.\n\n"നിങ്ങൾ മരണമെക്കുറിച്ച് ഭയപ്പെടുന്നത് നിങ്ങൾ സ്വയം അറിയാത്തതിനാലാണ്," മഹാരാജ് സൂചിപ്പിക്കാറുണ്ടായിരുന്നു. "യഥാർത്ഥ നിങ്ങൾ മരണമില്ലാത്തവനാണ്." ഈ മരണമെന്ന ഭയം നാശവാനായ ശരീരവുമായി തിരിച്ചറിയുന്നതിൽ നിന്നാണ് വരുന്നത്, അമരമായ ബോധമായി നിങ്ങളെ തിരിച്ചറിയുന്നതിന് പകരം.\n\nമഹാരാജ് നമ്മൾ യാഥാർത്ഥത്തിൽ ജനനം അല്ലെങ്കിൽ മരണം അനുഭവിച്ചിട്ടില്ല എന്ന് പഠിപ്പിച്ചു. നമുക്ക് ഭാവത്തിന്റെ കാഴ്ചപ്പാടുകളും, ഭവനത്തിന്റെ ഓർമ്മകളും ഉണ്ട്, പക്ഷേ നമ്മുടെ യാഥാർത്ഥ്യമായ അനുഭവം എപ്പോഴും ഇപ്പോഴത്തെ ബോധത്തിന്റെ നിമിഷത്തിലാണ്. ഈ ബോധം എപ്പോഴും ഉണ്ടായിരിക്കുന്നു, എപ്പോഴും ഉണ്ടായിരിക്കും. \n\nനിന്റെ മരണമില്ലാത്ത സ്വഭാവത്തെ മനസ്സിലാക്കുന്നത് ഒരു വിശ്വാസമല്ല അല്ലെങ്കിൽ ആശ്വാസമല്ല, മറിച്ച് ഒരു നേരിട്ടുള്ള തിരിച്ചറിവാണ്. നീ നിന്റെ ശുദ്ധ ബോധമായി നന്നായി അറിയുമ്പോൾ, മരണം എന്നതിന്റെ ഭയം നശിക്കുന്നു, കാരണം നീ മരിക്കുന്ന ഒന്നും ഇല്ലെന്ന് നീ തിരിച്ചറിഞ്ഞിരിക്കുന്നു. \n\n"നിന്റെ ദുർബലത എനിക്ക് പറയുന്നത്, നീ ലോകത്തിൽ ജനിച്ചുവെന്ന വിശ്വാസമാണ്," അദ്ദേഹം പറയുമായിരുന്നു. യാഥാർത്ഥ്യത്തിൽ, ലോകം നിനക്കുള്ളിൽ പ്രത്യക്ഷപ്പെടുന്നു; നീ ലോകത്തിൽ പ്രത്യക്ഷപ്പെടുന്നില്ല. ഈ അടിസ്ഥാനപരമായ മനസ്സിലാക്കലിലെ മാറ്റം നിന്റെ ജീവിതത്തോടും മരണമോടും ഉള്ള മുഴുവൻ ബന്ധത്തെ മാറ്റുന്നു. \n\nഈ ഉപദേശത്തിന്റെ പ്രായോഗിക അർത്ഥം വലിയ സ്വാതന്ത്ര്യവും ഭയമില്ലായ്മയും ആണ്. നിങ്ങൾ മരണമില്ലാത്ത യാഥാർത്ഥ്യമായി നിങ്ങളെ അറിയുമ്പോൾ, നിങ്ങളുടെ സ്വാഭാവിക സന്തോഷവും സമാധാനവും മൃത്യുവിന്റെ നിഴലാൽ മൂടപ്പെടാതെ, നിങ്ങൾ മുഴുവൻ ജീവിക്കാനും പൂർണ്ണമായും സ്നേഹിക്കാനും കഴിയും.'
    ),
  ],
);
